def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c

    if op_d == 0:
        return 'C'
    if op_c == 0:
        return 'D'

    last = op[-1]
    run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == last:
            run += 1
        else:
            break

    if last == 'D':
        if run >= 2:
            # Allow a second cooperative move after starting a test, to let a
            # TFT-like opponent copy our cooperation and restore mutual C.
            if me[-1] == 'C' and len(me) >= 2 and me[-2] == 'D' and op_c * 2 > n:
                return 'C'
            # Test for TFT-like opponent during a long DD streak.
            if run >= 5 and op_c * 2 > n and me[-1] == 'D' and me[-2] == 'D' and me[-3] == 'D' and me[-4] == 'D':
                return 'C'
            return 'D'
        # run == 1
        if op_d * 3 > n:
            return 'D'
        if me and me[-1] == 'D':
            return 'C'
        return 'D'

    if n == 100:
        return 'D'

    if op_c * 5 >= n * 4:
        if n >= 95 and rng.random() < 0.25:
            return 'D'
        return 'C'

    if op_d * 2 > n:
        return 'D'

    if me and op:
        if op[-1] == 'D' and len(op) >= 2 and op[-2] == 'C':
            return 'C'
        return op[-1]
    return 'C'
